//! Cargo-driven `mscoree.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x72020000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fede000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fede000000u64)),
        o => panic!("mscoree-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "engine:oldnames", "import:dbghelp", "import:advapi32", "import:shell32", "import:kernel32_vista", "import:ole32", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["engine:uuid", "engine:wine", "engine:oldnames", "import:dbghelp", "import:advapi32", "import:shell32", "import:kernel32_vista", "import:ole32", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["engine:uuid", "engine:wine", "engine:oldnames", "import:dbghelp", "import:advapi32", "import:shell32", "import:kernel32_vista", "import:ole32", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/mscoree",
        "dll/win32/mscoree",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "USE_NEW_WINE_REGISTER_RESOURCES",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x600",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("mscoree_shims", &["dll/win32/mscoree/assembly.c", "dll/win32/mscoree/config.c", "dll/win32/mscoree/cordebug.c", "dll/win32/mscoree/corruntimehost.c", "dll/win32/mscoree/metadata.c", "dll/win32/mscoree/metahost.c", "dll/win32/mscoree/mscoree_main.c", "dll/win32/mscoree/reactos.c", "dll/win32/mscoree/guid.c"])
        .rc("dll/win32/mscoree/mscoree.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/mscoree/mscoree.spec", "mscoree.dll")
        .spec_stubs()
        .import_lib("dll/win32/dbghelp/dbghelp.spec", "dbghelp.dll", "dbghelp")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
